# --- HTTP helpers -------------------------------------------------------------
def http_post(url, payload, headers, timeout=30):
    headers = {**headers, "User-Agent": USER_AGENT}
    body = json.dumps(payload).encode()
    req = urllib.request.Request(url, data=body, headers=headers, method="POST")
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return r.status, json.loads(r.read().decode())
    except urllib.error.HTTPError as e:
        return e.code, {"error": e.read().decode()}

# --- Step 1: parallel fetch ---------------------------------------------------
cutoff_ms = int((datetime.now(timezone.utc) - timedelta(hours=WINDOW_HRS)).timestamp() * 1000)

def fetch_agent(name, aid):
    status, data = http_post(
        "https://api.retellai.com/v2/list-calls",
        {"filter_criteria": {"agent_id": [aid]}, "limit": 50, "sort_order": "descending"},
        {"Authorization": f"Bearer {RETELL_KEY}", "Content-Type": "application/json"},
    )
    if status != 200:
        return name, [], f"HTTP {status}: {data.get('error','')[:200]}"
    calls = data if isinstance(data, list) else data.get("calls", data)
    recent = [c for c in calls if (c.get("start_timestamp") or 0) >= cutoff_ms]
    for c in recent:
        c["_centre"] = name
    return name, recent, None

all_calls, errors = [], {}
with ThreadPoolExecutor(max_workers=13) as ex:
    futs = {ex.submit(fetch_agent, n, a): n for n, a in AGENTS.items()}
    for f in as_completed(futs):
        name, recent, err = f.result()
        if err: errors[name] = err
        all_calls.extend(recent)

# --- Step 2a: cross-reference Cekura test runs -------------------------------
# Cekura tests trigger Retell calls with empty `retell_llm_dynamic_variables`
# AND no `CEKURA_TEST` markers when the scenario lacks a test_profile.
# Match by (Retell agent_id, to_number, ±60s of Cekura created_at).
cekura_test_keys = set()  # set of (retell_agent_id, to_number, start_min)
cekura_lookup_status = "skipped (no CEKURA_API_KEY)"
if CEKURA_KEY:
    cekura_lookup_count = 0
    err_count = 0
    cutoff_iso = (datetime.now(timezone.utc) - timedelta(hours=WINDOW_HRS + 2)).isoformat(timespec="seconds")
    def fetch_cekura_results(retell_aid, cekura_aid):
        url = f"https://api.cekura.ai/test_framework/v1/results/?agent_id={cekura_aid}&page_size=100"
        req = urllib.request.Request(url, headers={
            "X-CEKURA-API-KEY": CEKURA_KEY, "User-Agent": USER_AGENT,
        })
        try:
            with urllib.request.urlopen(req, timeout=20) as r:
                return retell_aid, json.loads(r.read().decode()), None
        except urllib.error.HTTPError as e:
            return retell_aid, None, f"HTTP {e.code}"
        except Exception as e:
            return retell_aid, None, str(e)[:100]

    with ThreadPoolExecutor(max_workers=8) as ex:
        futs = [ex.submit(fetch_cekura_results, raid, caid)
                for raid, caid in CEKURA_AGENT_IDS.items() if raid in AGENTS.values()]
        for f in as_completed(futs):
            raid, data, err = f.result()
            if err:
                err_count += 1; continue
            for result in (data or {}).get("results", []):
                created = result.get("created_at", "")
                if not created or created < cutoff_iso:
                    continue
                # Cekura created_at is just before the Retell call start
                try:
                    cdt = datetime.fromisoformat(created.replace("Z", "+00:00"))
                except Exception:
                    continue
                for run in result.get("runs", []):
                    num = run.get("number")
                    if not num: continue
                    cekura_lookup_count += 1
                    # Bucket by minute — Retell start is typically within 0-90s of Cekura created
                    for offset_sec in range(-60, 121, 30):
                        ts = cdt + timedelta(seconds=offset_sec)
                        cekura_test_keys.add((raid, num, ts.strftime("%Y-%m-%dT%H:%M")))
    cekura_lookup_status = f"matched {cekura_lookup_count} Cekura runs across {len(CEKURA_AGENT_IDS)} agents (errors: {err_count})"

# --- Step 2b: filter Cekura tests --------------------------------------------
def is_cekura(c):
    # Marker-based detection (legacy)
    tp = (c.get("transcript") or c.get("transcript_preview") or "")
    if "CEKURA_TEST" in tp: return True
    md = c.get("metadata") or {}
    if "CEKURA_TEST" in str(md.get("lead_id", "")): return True
    # 0-duration not_connected is most often a Cekura artifact
    if c.get("call_status") == "not_connected" and (c.get("duration_ms") or 0) == 0:
        return True
    # Cross-referenced test run (catches scenarios with empty test_profile_data)
    aid = c.get("agent_id")
    num = c.get("to_number")
    ts_ms = c.get("start_timestamp") or 0
    if aid and num and ts_ms:
        key_min = datetime.fromtimestamp(ts_ms / 1000, tz=timezone.utc).strftime("%Y-%m-%dT%H:%M")
        if (aid, num, key_min) in cekura_test_keys:
            return True
    return False

real = [c for c in all_calls if not is_cekura(c)]
cekura_n = len(all_calls) - len(real)

# --- Step 3: retry chains by to_number ---------------------------------------
chains = defaultdict(list)
for c in real:
    tn = c.get("to_number")
    if tn: chains[tn].append(c)

chain_summary = []  # (to_number, n_calls, max_attempt, centres, lead_first_name, flag)
for tn, calls in chains.items():
    if len(calls) < 2: continue
    calls.sort(key=lambda x: x.get("start_timestamp") or 0)
    max_attempt = max((c.get("metadata") or {}).get("retry_attempt", 0) or 0 for c in calls)
    centres = sorted({c["_centre"] for c in calls})
    # lead first name from custom_analysis_data.contact_name or metadata.first_name
    first_name = ""
    for c in calls:
        cad = (c.get("call_analysis") or {}).get("custom_analysis_data") or {}
        cn = cad.get("contact_name") or (c.get("metadata") or {}).get("first_name") or ""
        if cn:
            first_name = cn.split()[0]
            break
    flag = ""
    if max_attempt > 4: flag = "CAP_BREACH"
    # Gap analysis (business hours window 13:00-23:00 UTC = 9-7 EDT-ish)
    gaps_min = []
    for i in range(1, len(calls)):
        prev = calls[i-1].get("start_timestamp") or 0
        cur  = calls[i].get("start_timestamp") or 0
        if prev and cur:
            gaps_min.append((cur - prev) / 60000.0)
    if gaps_min and any(g > 180 for g in gaps_min) and not flag:
        flag = "SCHEDULER_LAG"
    if gaps_min and any(g < 60 for g in gaps_min) and not flag:
        flag = "PREMATURE_FIRE"
    chain_summary.append((tn, len(calls), max_attempt, ",".join(centres), first_name, flag))

# --- Step 4: categorize -------------------------------------------------------
buckets = defaultdict(list)
for c in real:
    cad = (c.get("call_analysis") or {}).get("custom_analysis_data") or {}
    cs  = c.get("call_status")
    drs = c.get("disconnection_reason")
    dur = c.get("duration_ms") or 0
    if cad.get("appointment_booked") is True:
        buckets["Booked"].append(c)
    elif c.get("in_voicemail") or drs == "voicemail_reached":
        buckets["Voicemail"].append(c)
    elif cad.get("decline_reason") == "busy":
        buckets["Busy"].append(c)
    elif cad.get("decline_reason") == "not_interested":
        buckets["NotInterested"].append(c)
    elif cs == "not_connected":
        buckets["NotConnected"].append(c)
    elif drs == "inactivity":
        buckets["Inactivity"].append(c)
    elif drs == "user_hangup" and dur < 15000:
        buckets["QuickHangup"].append(c)
    elif dur > 30000:
        buckets["Conversation"].append(c)
    else:
        buckets["Other"].append(c)

# --- Step 5: transcript-level issue checks (deterministic + optional LLM) -----
issues = []  # (severity, kind, centre, ident, call_id, evidence)

# 5B Data Capture Gaps on Booked
for c in buckets["Booked"]:
    cad = (c.get("call_analysis") or {}).get("custom_analysis_data") or {}
    missing = [k for k in ("child_age", "tour_date", "tour_time") if not cad.get(k)]
    if missing:
        issues.append(("MEDIUM", "Booking missing fields", c["_centre"],
                       c.get("to_number") or "?", c.get("call_id") or "?",
                       "missing: " + ", ".join(missing)))

# 5E Wrong Location
for c in real:
    cad = (c.get("call_analysis") or {}).get("custom_analysis_data") or {}
    if cad.get("wrong_location_requested") is True:
        issues.append(("MEDIUM", "Wrong location requested", c["_centre"],
                       c.get("to_number") or "?", c.get("call_id") or "?",
                       cad.get("wrong_location_value", "") or ""))

# 5G Retry Chain Anomaly (already computed)
for tn, n, attempt, centre, first, flag in chain_summary:
    if not flag: continue

